"""
SQLAlchemy 2.0 ORM model for improvement proposals.

Table: improvement_proposal
"""
from __future__ import annotations

from datetime import datetime
from typing import Any, Optional
from uuid import UUID, uuid4

import sqlalchemy as sa
from sqlalchemy import text
from sqlalchemy.dialects.postgresql import ARRAY, JSONB, TIMESTAMPTZ
from sqlalchemy.dialects.postgresql import UUID as PG_UUID
from sqlalchemy.orm import Mapped, mapped_column

from src.ai.memory.models.base import MemoryBase


class ImprovementProposal(MemoryBase):
    """Pending human-approval change proposal generated by the improvement loop."""

    __tablename__ = "improvement_proposal"

    proposal_id: Mapped[UUID] = mapped_column(
        PG_UUID(as_uuid=True),
        primary_key=True,
        default=uuid4,
        server_default=text("gen_random_uuid()"),
    )
    proposal_type: Mapped[str] = mapped_column(sa.String(), nullable=False)
    description: Mapped[Optional[str]] = mapped_column(sa.Text(), nullable=True)
    proposed_changes: Mapped[Optional[dict[str, Any]]] = mapped_column(
        JSONB(), nullable=True
    )
    status: Mapped[str] = mapped_column(
        sa.String(), nullable=False, server_default=text("'pending'")
    )
    reviewed_by: Mapped[Optional[UUID]] = mapped_column(
        PG_UUID(as_uuid=True), nullable=True
    )
    reviewed_at: Mapped[Optional[datetime]] = mapped_column(TIMESTAMPTZ(), nullable=True)
    created_at: Mapped[datetime] = mapped_column(
        TIMESTAMPTZ(), nullable=False, server_default=text("NOW()")
    )
    source_feedback_ids: Mapped[list[UUID]] = mapped_column(
        ARRAY(PG_UUID(as_uuid=True)),
        server_default=text("'{}'::uuid[]"),
    )
